#include "TelemetryOutbox.h"
#include <algorithm>
#include <cctype>
namespace NeoEngine { namespace {template<class T>void Put(std::vector<uint8_t>&o,T v){for(size_t i=0;i<sizeof(T);++i)o.push_back(static_cast<uint8_t>((static_cast<uint64_t>(v)>>(i*8))&255));}template<class T>bool Get(const std::vector<uint8_t>&b,size_t&n,T&v){if(n+sizeof(T)>b.size())return false;uint64_t x=0;for(size_t i=0;i<sizeof(T);++i)x|=static_cast<uint64_t>(b[n+i])<<(i*8);n+=sizeof(T);v=static_cast<T>(x);return true;}}bool TelemetryOutbox::ValidId(const std::string&id){if(id.empty()||id.size()>96)return false;for(unsigned char c:id)if(!std::isalnum(c)&&c!='-'&&c!='_')return false;return true;}bool TelemetryOutbox::Enqueue(std::string id,std::string json){if(!ValidId(id)||json.empty()||json.size()>kMaxEnvelopeBytes||json.front()!='{'||std::any_of(m_Pending.begin(),m_Pending.end(),[&](const auto&e){return e.id==id;})||m_Pending.size()==kMaxEnvelopes)return false;m_Pending.push_back({std::move(id),std::move(json)});return true;}bool TelemetryOutbox::Acknowledge(const std::string&id){auto it=std::find_if(m_Pending.begin(),m_Pending.end(),[&](const auto&e){return e.id==id;});if(it==m_Pending.end())return false;m_Pending.erase(it);return true;}std::vector<uint8_t> TelemetryOutbox::Serialize()const{std::vector<uint8_t>o;Put<uint32_t>(o,0x5842544FULL);Put<uint16_t>(o,1);Put<uint32_t>(o,m_Pending.size());for(const auto&e:m_Pending){Put<uint16_t>(o,e.id.size());o.insert(o.end(),e.id.begin(),e.id.end());Put<uint32_t>(o,e.json.size());o.insert(o.end(),e.json.begin(),e.json.end());}return o;}bool TelemetryOutbox::Deserialize(const std::vector<uint8_t>&b){size_t n=0;uint32_t magic,count;uint16_t ver;if(!Get(b,n,magic)||!Get(b,n,ver)||!Get(b,n,count)||magic!=0x5842544FULL||ver!=1||count>kMaxEnvelopes)return false;std::vector<TelemetryEnvelope>next;for(uint32_t i=0;i<count;++i){uint16_t il;uint32_t jl;if(!Get(b,n,il)||n+il>b.size())return false;std::string id(reinterpret_cast<const char*>(b.data()+n),il);n+=il;if(!Get(b,n,jl)||jl>kMaxEnvelopeBytes||n+jl>b.size()||!ValidId(id))return false;std::string json(reinterpret_cast<const char*>(b.data()+n),jl);n+=jl;if(json.empty()||json.front()!='{'||std::any_of(next.begin(),next.end(),[&](const auto&e){return e.id==id;}))return false;next.push_back({std::move(id),std::move(json)});}if(n!=b.size())return false;m_Pending=std::move(next);return true;} }
